  'base-render.components-flow-ribbon-forms.c007': "Cross matrix: rows are {p0} sources ({p1}), columns are {p2} use categories ({p3}); each cell shows the amount and its share of the total, bar length = this cell ÷ the largest cell {p4} {p5}; {p6} {p7} in total, row sums = column sums",
  /* ── packages/base-render/src/components/flow-ribbon/style-forms.ts（#1226 迁入） ── */
  'base-render.components-flow-ribbon-style-forms.c001': "/* ── Sankey ribbons: two node columns + a set of ribbons in between ────────────────────────────\n   Node heights and the top/bottom edges of both ribbon ends are **all computed percentages** (one ruler in model.ts),\n   so only position and appearance are written here; the ribbon polygons come from four inline custom properties. */",
  'base-render.components-flow-ribbon-style-forms.c002': '/* ── Cross matrix: rows = sources, columns = uses ────────────────────────────────\n   The share-drawn bar becomes "bar length" in the matrix: --flow-ribbon-w is this cell ÷ **the largest cell in the table**\n   (not the largest in this row — otherwise the deepest cell of every row would look equally important). */',
  /* ── packages/base-render/src/components/flow-ribbon/style-rails.ts（#1226 迁入） ── */
  'base-render.components-flow-ribbon-style-rails.c001': "/* ── Two composition rails + the meeting reading in between ──────────────────────────────────\n   Each cell's width = this cell's share of the total: **one total, each rail filling its own 100%**, so the two rails compare across.\n   Width is written on width (not pushed by content), which is exactly the pit the prototype stage fell into (flex: 0 0 auto sizing by text width). */",
  /* ── packages/base-render/src/components/flow-ribbon/style.ts（#1226 迁入） ── */
  'base-render.components-flow-ribbon-style.c001': "/* flow-ribbon (flow ribbon): three skeletons — Sankey ribbons / cross matrix / two composition rails + meeting reading.",
  'base-render.components-flow-ribbon-style.c002': "   One ruler runs through all three geometries: every 1% of height/width = the same amount of money (computed from the total and the span, written into inline styles in the markup).",
  'base-render.components-flow-ribbon-style.c003': "   Colours are always derived from the accent family (pale wash), readings are never truncated; width is judged by the container alone. */",
