  /* ── packages/base-render/src/components/multi-checks/style.ts（#1226 迁入） ── */
  'base-render.components-multi-checks-style.c001': '/* multi-checks (multi-select list · form A "select-all on top + grouped checkboxes + actions below"): pick first, then bulk-edit.',
  'base-render.components-multi-checks-style.c002': "   Hierarchy comes not from shadows or large radii (receipt paper has zero shadow, headline type zero radius): hairlines, weight and scale steps ⇒ reskinning only swaps values. */",
  'base-render.components-multi-checks-style.c003': '/* The box brings its own paper (no outer page frame needed): a clear boundary, otherwise "where does the list end" is invisible. */',
  'base-render.components-multi-checks-style.c004': '/* The sentence on top, "what this list is for": main text + secondary segment, both may wrap (**never truncated with `…`**). */',
  'base-render.components-multi-checks-style.c005': "/* Select-all head: one master switch + the selected count. A hairline separates it from the list. */",
  'base-render.components-multi-checks-style.c006': "/* Selected count: tabular digits (no reflow when the digit count widens). **No `nowrap`**: overflow looks worse than a wrap. */",
  'base-render.components-multi-checks-style.c007': "/* Checkbox: square (unchecked) → square + tick (checked). Box and tick are **shapes**, not colour. */",
  'base-render.components-multi-checks-style.c008': "/* The real state always lives on the native box: both the checked and the mixed appearance start from `:checked` and `:indeterminate`. */",
  'base-render.components-multi-checks-style.c009': '/* The tick (the second cue: a word); the mixed state uses a dash (shape tells "partly checked" from "all checked"). */',
  'base-render.components-multi-checks-style.c010': "/* The native box: visually hidden but **still in the accessibility tree** (1px box + `opacity:0`, not `display:none`). */",
  'base-render.components-multi-checks-style.c011': "/* The per-item column: a hairline between groups. */",
  'base-render.components-multi-checks-style.c012': "/* Group head: the whole block is the hit area (checking it checks the whole group); its fill differs from the rows so you see at a glance which rows form a group. */",
  'base-render.components-multi-checks-style.c013': "/* One row: checkbox + main text (with secondary line) + amount on the right. The whole row is the hit area (≥48px). */",
  'base-render.components-multi-checks-style.c014': "/* Secondary line and disabled reason: one line of small text each (absent when not given, no empty slot left). */",
  'base-render.components-multi-checks-style.c015': "/* Amount: tabular digits on the right. **No `nowrap`**: when an amount is too long to fit, wrap rather than overflow sideways. */",
  'base-render.components-multi-checks-style.c016': "/* A checked row: first cue (shape) = a vertical bar on the left; third cue (colour) = soft fill. */",
  'base-render.components-multi-checks-style.c017': "/* Mouse hover is only a **hint**, not the only path (checking and focus each have their own mark). */",
  'base-render.components-multi-checks-style.c018': "/* Focus: when the native box takes keyboard focus the whole row / block shows it (**visible focus, ≥2px**). */",
  'base-render.components-multi-checks-style.c019': "/* The bottom row: total + action buttons (buttons **below** — that is exactly this form's shape). */",
  'base-render.components-multi-checks-style.c020': '/* Primary button: accent fill + text on the accent fill (`accent-ink` is the "text on accent fill" tier).',
  'base-render.components-multi-checks-style.c021': "   Hung off `data-*` markers (not a modifier class like `is-primary`: short class names collide with other components). */",
  'base-render.components-multi-checks-style.c022': "/* Real press: shrink one notch (bounces back within ≤80ms; transform only, no layout). */",
  'base-render.components-multi-checks-style.c023': '/* Not pressable: `cursor: not-allowed` + point "why" at the reading below (`aria-describedby`). */',
  'base-render.components-multi-checks-style.c024': "/* Disabled and loading: the row cannot be tapped (the reason sentence is rendered into the row by the markup). Disabled is judged by **native** `:has(input[disabled])`;",
  'base-render.components-multi-checks-style.c025': "   loading is judged by the `data-*` on the root — state has exactly one source of truth, no extra modifier class. */",
  'base-render.components-multi-checks-style.c026': "/* The empty-state and loading sentence: muted text + designed padding (not leftover whitespace). */",
  'base-render.components-multi-checks-style.c027': "/* Error state: written beside the control (not colour alone), with a marker word. */",
  'base-render.components-multi-checks-style.c028': "/* Narrow container (<{p0}px): the amount starts a new line, left-aligned (no longer competing with the main text for that line).",
  'base-render.components-multi-checks-style.c029': "   The judge is **this component's own width**: it gets embedded in sidebars, panels and cards, so viewport width ≠ component width (hence no `@media` here). */",
  'base-render.components-multi-checks-style.c030': "/* Motion preference: switch off transitions only, never states (no state may stall midway ⇒ nothing is driven by `transitionend`). */",
