  'base-render.components-range-bar-style.c017': '/* Track: a hairline at each end (so you can read "where the axis starts and ends"); the interval is positioned in percent, always inside the axis. */',
  'base-render.components-range-bar-style.c018': "/* The duration text inside a segment: written on a **small card surface chip** (text on light/dark blocks does not gamble on step luminance, it stays legible after a reskin).",
